import { z } from "zod";
import snapshot from "./release-notes.json";

export const ReleaseNote = z.object({
    id: z.string().regex(/^[a-f0-9]{40}$/),
    date: z.string().datetime({ offset: true }),
    author: z.string().min(1),
    type: z.enum(["feat", "fix"]),
    description: z.string().min(1),
});
export type ReleaseNote = z.infer<typeof ReleaseNote>;
export const ReleaseNotes = z.array(ReleaseNote);

/** Snapshot of the commits included in this build, regenerated by the image build workflow. */
export const releaseNotes = ReleaseNotes.parse(snapshot);

export function getNewReleaseNotes(deployed: ReleaseNote[], loaded: ReleaseNote[]): ReleaseNote[] {
    const knownIds = new Set(loaded.map((note) => note.id));
    return deployed.filter((note) => !knownIds.has(note.id));
}
